package chainledger

import (
	"encoding/json"
	"fmt"
	"sort"
	"unicode/utf8"
)

// lineageExportEdge is one direct dependency in an exported lineage document,
// written in the actual derivation direction: From is the upstream dataset and
// To is the dataset derived from it.
type lineageExportEdge struct {
	From string `json:"from"`
	To   string `json:"to"`
}

// lineageExportDocument is the JSON shape produced by the lineage exports:
// the set of dataset names involved in the requested derivation, plus every
// direct dependency between them.
type lineageExportDocument struct {
	Nodes []string            `json:"nodes"`
	Edges []lineageExportEdge `json:"edges"`
}

// ExportUpstreamLineage exports the complete upstream lineage of target as a
// JSON document, for other programs to consume. Where Upstreams explains each
// source with a single shortest path, this export preserves every branch the
// target actually depends on: even when a source already reaches the target
// directly, the longer routes through intermediate datasets stay in the
// document.
//
// The document's top level holds two arrays:
//
//   - "nodes": the names of target itself and every direct and indirect
//     upstream of it, each exactly once, ordered by Go string order.
//   - "edges": every direct dependency between the included nodes, each
//     exactly once, written {"from": upstream, "to": derived} in the actual
//     derivation direction and ordered by "from" and then "to", again in Go
//     string order.
//
// The target's downstreams and datasets that take no part in its derivation
// never appear. A target with no upstreams exports successfully with itself
// as the only node and an empty (non-null) edges array. The ordering is fully
// determined by the names, so neither registration order nor the stored
// upstream list order can change the output; names are matched by exact
// registered value (case-sensitive) and written verbatim, with JSON escaping
// applied so a reader recovers the original bytes.
//
// Every name in the exported set must be valid UTF-8: JSON cannot carry an
// invalid byte sequence losslessly (a JSON encoder would replace it with the
// replacement character and two distinct names could collapse into one), so a
// success guarantees the reader recovers every name exactly as registered. If
// any included node's name is not valid UTF-8, the whole export fails; the
// error identifies the offending name in Go-quoted form (%q), which renders
// each non-displayable byte as its own \xNN escape, so different bad bytes
// never share one replacement glyph. When several names are invalid, the one
// sorting first in Go string order is reported, keeping the error independent
// of registration and stored-list order. Only the target and its ancestors are
// inspected: an unrelated dataset or a downstream of the target may hold an
// invalid name without blocking this export. A real replacement character
// (U+FFFD) that is itself part of a name is valid UTF-8 and exports normally.
//
// The export is read-only: it changes no node, edge or stored list order. An
// empty target is rejected as a missing name; a target absent from the graph
// (including an empty or nil graph) is rejected with an error naming it, and
// those checks take precedence over name encoding. Failures return an empty
// string and never a partial document.
func ExportUpstreamLineage(graph map[string]*Lineage, target string) (string, error) {
	if target == "" {
		return "", errInvalid("dataset name is required")
	}
	if _, ok := graph[target]; !ok {
		return "", errInvalid("dataset not found: " + target)
	}

	return renderLineageExport(graph, ancestorClosure(graph, target))
}

// ExportSourceTargetLineage exports only the part of target's upstream lineage
// that a specified registered source actually participates in, as a JSON
// document for other programs to consume. Where ExportUpstreamLineage brings
// along every source target depends on, this scoped export answers just "how
// does this one source derive this target".
//
// The document holds exactly the datasets that lie on at least one existing
// derivation route from source to target — source and target included — and
// exactly the direct dependencies carried by those routes. Concretely a node
// is included when it is both a direct or indirect downstream of source and a
// direct or indirect upstream of target; an edge is included when both of its
// endpoints are. Every node and edge appears once. Keeping the full node set
// (rather than one picked path) preserves every branch simultaneously: if
// source reaches target directly, through a, and through b and mid, limiting
// the export to source and report still keeps all three routes complete — a
// longer route is never dropped because a direct relation or a shorter route
// exists.
//
// What stays out follows from the same intersection:
//
//   - An independent source that feeds an included intermediate dataset but is
//     not itself downstream of source is excluded, and so is the edge from it:
//     if a additionally depends on extra, neither extra nor extra -> a appears.
//   - A downstream of source that cannot reach target is excluded; ancestors
//     of source and downstreams of target are excluded as well.
//
// When source and target are the same registered dataset, that dataset alone
// is exported with an empty edges array. When both are registered but no
// derivation route from source to target exists, the export still succeeds but
// holds two empty (non-null) arrays — no isolated endpoint is retained, and a
// dependency running the other way (target derives source) is not treated as
// reachability.
//
// The document shape, the {"from": upstream, "to": derived} edge direction,
// the nodes-by-name and edges-by-from-then-to Go-string ordering, the
// byte-exact name handling and the invalid-UTF-8 failure rule all match
// ExportUpstreamLineage, judged over the scoped node set only: a name outside
// the selected routes, including one on target's other ancestry, never blocks
// this export. Output is therefore fully determined by the registered names
// and independent of registration order and stored upstream-list order.
//
// Names match by exact registered value (case-sensitive). Source is validated
// first: an empty name is a missing-name error and an unregistered name
// (including against an empty or nil graph) is an error naming it; only then
// is target checked the same way. Those checks take precedence over name
// encoding. The export is read-only — it changes no node, bidirectional
// relationship or stored list order — and any failure returns an empty
// string, never a partial document.
func ExportSourceTargetLineage(graph map[string]*Lineage, source, target string) (string, error) {
	if source == "" {
		return "", errInvalid("dataset name is required")
	}
	if _, ok := graph[source]; !ok {
		return "", errInvalid("dataset not found: " + source)
	}
	if target == "" {
		return "", errInvalid("dataset name is required")
	}
	if _, ok := graph[target]; !ok {
		return "", errInvalid("dataset not found: " + target)
	}

	// A node belongs to a source -> target derivation exactly when it is
	// downstream of source AND upstream of target. Register rejects cycles, so
	// both walks terminate; the visited sets guard the loops regardless.
	downstream := descendantClosure(graph, source)
	upstream := ancestorClosure(graph, target)
	included := make(map[string]bool)
	for name := range downstream {
		if upstream[name] {
			included[name] = true
		}
	}

	return renderLineageExport(graph, included)
}

// ancestorClosure collects start and every dataset reachable from it by
// following parent edges.
func ancestorClosure(graph map[string]*Lineage, start string) map[string]bool {
	included := map[string]bool{start: true}
	queue := []string{start}
	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]
		for _, parent := range graph[node].Parents {
			if !included[parent] {
				included[parent] = true
				queue = append(queue, parent)
			}
		}
	}
	return included
}

// descendantClosure collects start and every dataset reachable from it by
// following child edges.
func descendantClosure(graph map[string]*Lineage, start string) map[string]bool {
	included := map[string]bool{start: true}
	queue := []string{start}
	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]
		for _, child := range graph[node].Children {
			if !included[child] {
				included[child] = true
				queue = append(queue, child)
			}
		}
	}
	return included
}

// renderLineageExport serializes one already-decided node set in the single
// document format shared by the lineage exports.
func renderLineageExport(graph map[string]*Lineage, included map[string]bool) (string, error) {
	nodes := make([]string, 0, len(included))
	for name := range included {
		nodes = append(nodes, name)
	}
	sort.Strings(nodes)

	// JSON text must round-trip every name byte for byte. encoding/json would
	// silently rewrite an invalid UTF-8 byte sequence into U+FFFD rather than
	// fail, and two byte-different names could then decode to the same value,
	// so check the included names ourselves before any document is produced.
	// Nodes are already in Go string order, so the first invalid one is the
	// deterministic answer regardless of registration or upstream-list order;
	// %q exposes the actual bytes (non-displayable ones as \xNN) instead of a
	// shared replacement glyph. Nodes outside the selected set are never
	// examined.
	for _, name := range nodes {
		if !utf8.ValidString(name) {
			return "", errInvalid(fmt.Sprintf(
				"dataset name is not valid UTF-8 and cannot be exported losslessly: %q", name))
		}
	}

	// Every direct dependency between included nodes is an edge. In the full
	// upstream export every parent of an included node is included by
	// construction; in a source-scoped export an included intermediate node may
	// also depend on an independent, excluded source, so the parent has to be
	// checked against the set. The dedupe set guards the one-edge-once rule even
	// if a stored list ever repeated a name.
	edges := make([]lineageExportEdge, 0)
	seen := make(map[lineageExportEdge]bool)
	for _, name := range nodes {
		for _, parent := range graph[name].Parents {
			if !included[parent] {
				continue
			}
			edge := lineageExportEdge{From: parent, To: name}
			if !seen[edge] {
				seen[edge] = true
				edges = append(edges, edge)
			}
		}
	}
	sort.Slice(edges, func(i, j int) bool {
		if edges[i].From != edges[j].From {
			return edges[i].From < edges[j].From
		}
		return edges[i].To < edges[j].To
	})

	data, err := json.Marshal(lineageExportDocument{Nodes: nodes, Edges: edges})
	if err != nil {
		return "", err
	}
	return string(data), nil
}

package chainledger

import (
	"reflect"
	"strings"
	"testing"
)

// scopedReregisterScenario builds the regression lineage: source derives merge
// directly, through the short branch short, and through the longer branch
// longa -> longb; merge additionally depends on the independent root indie.
// merge derives target, target derives view, and spare stands alone.
func scopedReregisterScenario(t *testing.T) map[string]*Lineage {
	t.Helper()
	return buildRegisteredGraph(t, [][]string{
		{"source"},
		{"short", "source"},
		{"longa", "source"},
		{"longb", "longa"},
		{"indie"},
		{"merge", "source", "short", "longb", "indie"},
		{"target", "merge"},
		{"view", "target"},
		{"spare"},
	})
}

// The exact JSON texts of the source -> target scoped export before the
// replacement and after each replacement variant. Both orderings are fully
// determined by the names.
const (
	scopedReregisterBefore = `{"nodes":["longa","longb","merge","short","source","target"],` +
		`"edges":[{"from":"longa","to":"longb"},{"from":"longb","to":"merge"},` +
		`{"from":"merge","to":"target"},{"from":"short","to":"merge"},` +
		`{"from":"source","to":"longa"},{"from":"source","to":"merge"},` +
		`{"from":"source","to":"short"}]}`
	scopedReregisterLongOnly = `{"nodes":["longa","longb","merge","source","target"],` +
		`"edges":[{"from":"longa","to":"longb"},{"from":"longb","to":"merge"},` +
		`{"from":"merge","to":"target"},{"from":"source","to":"longa"}]}`
	scopedReregisterBothBranches = `{"nodes":["longa","longb","merge","short","source","target"],` +
		`"edges":[{"from":"longa","to":"longb"},{"from":"longb","to":"merge"},` +
		`{"from":"merge","to":"target"},{"from":"short","to":"merge"},` +
		`{"from":"source","to":"longa"},{"from":"source","to":"short"}]}`
)

// Focus regression: replacing merge's direct-upstream list drops the direct
// source -> merge edge and the short branch while keeping the longer
// source -> longa -> longb -> merge route and the independent upstream indie.
// The scoped export must keep every node and direct dependency on the
// surviving long route — source and merge included — while short leaves the
// document even though it stays registered and is still a downstream of
// source. indie and the indie -> merge edge, target's downstream view, and
// the standalone spare never enter the document.
func TestExportSourceTargetLineageAfterReregisterKeepsLongRoute(t *testing.T) {
	graph := scopedReregisterScenario(t)
	assertConsistent(t, graph)

	// Before the replacement all three routes plus the merge node are present;
	// indie, view and spare stay out.
	if out := mustExportScoped(t, graph, "source", "target"); out != scopedReregisterBefore {
		t.Errorf("export before re-register =\n%s\nwant:\n%s", out, scopedReregisterBefore)
	}

	// Replace merge's whole direct-upstream list: drop source (direct) and
	// short, keep longb and indie.
	mustRegister(t, graph, "merge", "longb", "indie")
	assertConsistent(t, graph)
	assertEntry(t, graph, "merge", []string{"longb", "indie"}, []string{"target"})
	// short left merge's upstream list but keeps its own registration and its
	// surviving source -> short dependency; it is still a downstream of source.
	assertEntry(t, graph, "short", []string{"source"}, nil)
	assertEntry(t, graph, "source", nil, []string{"short", "longa"})
	assertEntry(t, graph, "longa", []string{"source"}, []string{"longb"})
	assertEntry(t, graph, "longb", []string{"longa"}, []string{"merge"})
	assertEntry(t, graph, "indie", nil, []string{"merge"})
	assertEntry(t, graph, "target", []string{"merge"}, []string{"view"})

	before := snapshotExportGraph(graph)
	out := mustExportScoped(t, graph, "source", "target")
	if out != scopedReregisterLongOnly {
		t.Errorf("export after re-register =\n%s\nwant:\n%s", out, scopedReregisterLongOnly)
	}
	doc := parseExport(t, out)

	// The surviving long route is complete: source, longa, longb, merge and
	// target each appear exactly once with every direct dependency along it.
	wantNodes := []string{"longa", "longb", "merge", "source", "target"}
	if !reflect.DeepEqual(doc.Nodes, wantNodes) {
		t.Errorf("nodes = %v, want %v", doc.Nodes, wantNodes)
	}
	wantEdges := [][2]string{
		{"longa", "longb"},
		{"longb", "merge"},
		{"merge", "target"},
		{"source", "longa"},
	}
	if got := exportEdgeNames(doc); !reflect.DeepEqual(got, wantEdges) {
		t.Errorf("edges = %v, want %v", got, wantEdges)
	}

	// short can no longer reach target, so it leaves the document; indie (and
	// indie -> merge), view and spare were never on a source -> target route.
	for _, excluded := range []string{"short", "indie", "view", "spare"} {
		for _, node := range doc.Nodes {
			if node == excluded {
				t.Errorf("nodes must not contain %q: %v", excluded, doc.Nodes)
			}
		}
	}
	for _, e := range doc.Edges {
		if e.From == "indie" {
			t.Errorf("independent upstream edge %v must stay out of %v", e, doc.Edges)
		}
	}

	// The export is read-only over the post-replacement state.
	assertGraphUnchanged(t, before, graph)
}

// Removing only the direct source -> merge dependency while keeping both the
// short and the long branch: the scoped export must present both routes
// completely — the longer route is not dropped because the shorter one
// exists — with the shared merge node and the merge -> target dependency
// appearing exactly once.
func TestExportSourceTargetLineageAfterReregisterKeepsBothBranches(t *testing.T) {
	graph := scopedReregisterScenario(t)
	assertConsistent(t, graph)

	mustRegister(t, graph, "merge", "short", "longb", "indie")
	assertConsistent(t, graph)
	assertEntry(t, graph, "merge", []string{"short", "longb", "indie"}, []string{"target"})
	assertEntry(t, graph, "source", nil, []string{"short", "longa"})

	before := snapshotExportGraph(graph)
	out := mustExportScoped(t, graph, "source", "target")
	if out != scopedReregisterBothBranches {
		t.Errorf("export after re-register =\n%s\nwant:\n%s", out, scopedReregisterBothBranches)
	}
	doc := parseExport(t, out)

	wantNodes := []string{"longa", "longb", "merge", "short", "source", "target"}
	if !reflect.DeepEqual(doc.Nodes, wantNodes) {
		t.Errorf("nodes = %v, want %v", doc.Nodes, wantNodes)
	}
	wantEdges := [][2]string{
		{"longa", "longb"},
		{"longb", "merge"},
		{"merge", "target"},
		{"short", "merge"},
		{"source", "longa"},
		{"source", "short"},
	}
	if got := exportEdgeNames(doc); !reflect.DeepEqual(got, wantEdges) {
		t.Errorf("edges = %v, want %v", got, wantEdges)
	}

	// The shared merge node and the merge -> target edge appear once each,
	// however many routes pass through them.
	mergeCount, mergeEdgeCount := 0, 0
	for _, node := range doc.Nodes {
		if node == "merge" {
			mergeCount++
		}
	}
	for _, e := range doc.Edges {
		if e.From == "merge" && e.To == "target" {
			mergeEdgeCount++
		}
	}
	if mergeCount != 1 || mergeEdgeCount != 1 {
		t.Errorf("shared merge appears %d times as node, %d as edge, want 1 each",
			mergeCount, mergeEdgeCount)
	}

	assertGraphUnchanged(t, before, graph)
}

// Replacing merge's upstream list with only the independent upstream indie
// leaves source and target registered but with no forward route between them:
// the scoped export succeeds with two empty (non-null) arrays — no isolated
// endpoint is retained, and no unregistered error is raised.
func TestExportSourceTargetLineageAfterReregisterNoRoute(t *testing.T) {
	graph := scopedReregisterScenario(t)
	assertConsistent(t, graph)

	mustRegister(t, graph, "merge", "indie")
	assertConsistent(t, graph)
	assertEntry(t, graph, "merge", []string{"indie"}, []string{"target"})
	// The replaced-away nodes keep their registrations and their surviving
	// dependencies: source still derives short and longa, longa still derives
	// longb; only the edges into merge are gone.
	assertEntry(t, graph, "source", nil, []string{"short", "longa"})
	assertEntry(t, graph, "longb", []string{"longa"}, nil)
	assertEntry(t, graph, "indie", nil, []string{"merge"})

	before := snapshotExportGraph(graph)
	out := mustExportScoped(t, graph, "source", "target")
	if want := `{"nodes":[],"edges":[]}`; out != want {
		t.Errorf("export = %s, want %s", out, want)
	}
	doc := parseExport(t, out)
	if len(doc.Nodes) != 0 || doc.Nodes == nil {
		t.Errorf("nodes must be a non-nil empty array, got %#v", doc.Nodes)
	}
	if len(doc.Edges) != 0 || doc.Edges == nil {
		t.Errorf("edges must be a non-nil empty array, got %#v", doc.Edges)
	}

	// Both endpoints are still registered: the empty document is a route
	// result, not a not-found error, and the graph is untouched by the query.
	assertEntry(t, graph, "source", nil, []string{"short", "longa"})
	assertEntry(t, graph, "target", []string{"merge"}, []string{"view"})
	assertGraphUnchanged(t, before, graph)
}

// A rejected replacement must not partially apply: re-registering merge with
// the registered spare followed by the unregistered ghost fails naming ghost,
// and the source -> target export afterwards is byte-identical to the
// pre-request text — spare never enters the document and no partial new
// relation leaks into the graph.
func TestExportSourceTargetLineageFailedReregisterLeavesExportUntouched(t *testing.T) {
	graph := scopedReregisterScenario(t)
	assertConsistent(t, graph)

	exportBefore := mustExportScoped(t, graph, "source", "target")
	if exportBefore != scopedReregisterBefore {
		t.Fatalf("export before failed re-register =\n%s\nwant:\n%s", exportBefore, scopedReregisterBefore)
	}
	before := snapshotExportGraph(graph)

	err := Register(graph, Dataset{Name: "merge"}, []string{"spare", "ghost"})
	if err == nil || !strings.Contains(err.Error(), "ghost") {
		t.Fatalf("want unknown-parent error naming ghost, got %v", err)
	}

	// No partial effect: merge never gained spare nor lost any upstream, and
	// the whole graph, list orders included, is exactly as before the request.
	assertGraphUnchanged(t, before, graph)
	assertEntry(t, graph, "merge", []string{"source", "short", "longb", "indie"}, []string{"target"})
	assertEntry(t, graph, "spare", nil, nil)
	assertConsistent(t, graph)

	// The export after the rejected request matches the pre-request text
	// exactly, with no trace of spare or a half-applied replacement.
	exportAfter := mustExportScoped(t, graph, "source", "target")
	if exportAfter != exportBefore {
		t.Errorf("export changed after rejected re-register:\nbefore: %s\nafter:  %s",
			exportBefore, exportAfter)
	}
	if strings.Contains(exportAfter, "spare") {
		t.Errorf("export must not contain spare after the rejected request: %s", exportAfter)
	}
	assertGraphUnchanged(t, before, graph)
}

package chainledger

import (
	"reflect"
	"strings"
	"testing"
)

// scopedRenameFixture builds the scoped-export rename regression lineage:
//
//	extra ──> mid (mid depends on an independent source as well)
//	source ──> mid ──> step ──> report (the long branch)
//	source ──> report                (the direct relation)
//	mid ──> report                   (mid also reaches report in one hop)
//	mid ──> sidedown                 (a mid downstream that never reaches report)
//	report ──> view                  (target downstream)
//	isolated                         (standalone)
//
// source derives report directly and through mid (both via mid -> report and
// via mid -> step -> report), so mid and report each lie on several routes and
// must still appear once each. extra, extra -> mid, sidedown, view and
// isolated never take part in source's derivation of report and stay out.
func scopedRenameFixture(t *testing.T) map[string]*Lineage {
	t.Helper()
	return buildRegisteredGraph(t, [][]string{
		{"source"},
		{"extra"},
		{"mid", "source", "extra"},
		{"step", "mid"},
		{"report", "source", "mid", "step"},
		{"sidedown", "mid"},
		{"view", "report"},
		{"isolated"},
	})
}

// The exact scoped JSON text before any rename: nodes in Go string order,
// edges upstream -> derived ordered by from then to.
const scopedRenameBefore = `{"nodes":["mid","report","source","step"],` +
	`"edges":[{"from":"mid","to":"report"},{"from":"mid","to":"step"},` +
	`{"from":"source","to":"mid"},{"from":"source","to":"report"},` +
	`{"from":"step","to":"report"}]}`

// After mid is renamed to zmid: the node moves from the front of the node
// list to the end, and its three edges (source -> zmid in, zmid -> report and
// zmid -> step out) move to their new from-then-to positions. The selected
// set and the direct dependencies are otherwise exactly the pre-rename ones —
// same four nodes, same five edges, only the name substituted.
const scopedRenameAfterZmid = `{"nodes":["report","source","step","zmid"],` +
	`"edges":[{"from":"source","to":"report"},{"from":"source","to":"zmid"},` +
	`{"from":"step","to":"report"},{"from":"zmid","to":"report"},` +
	`{"from":"zmid","to":"step"}]}`

// After zmid is renamed to amid: the node moves back to the front of the node
// list and its edges lead the edge array again. amid contains the old name's
// text ("mid") as a substring, yet matching is by full name: the document
// holds amid, and mid itself appears neither as a node nor as an edge
// endpoint.
const scopedRenameAfterAmid = `{"nodes":["amid","report","source","step"],` +
	`"edges":[{"from":"amid","to":"report"},{"from":"amid","to":"step"},` +
	`{"from":"source","to":"amid"},{"from":"source","to":"report"},` +
	`{"from":"step","to":"report"}]}`

// assertOldNameAbsent fails if oldName occurs as a node or as an edge
// endpoint in the document. The comparison is by full name, not substring:
// the new name may legitimately contain the old name's text.
func assertOldNameAbsent(t *testing.T, doc exportDocument, oldName string) {
	t.Helper()
	for _, node := range doc.Nodes {
		if node == oldName {
			t.Errorf("old name %q still present as a node: %v", oldName, doc.Nodes)
		}
	}
	for _, e := range doc.Edges {
		if e.From == oldName || e.To == oldName {
			t.Errorf("old name %q still present as an edge endpoint: %+v", oldName, e)
		}
	}
}

// Regression for the source-scoped export after an intermediate dataset on
// the derivation routes is renamed. The direct source -> report relation and
// the longer branches through the renamed node all survive: the export keeps
// answering "which existing relations let source participate in report's
// derivation", with every selected node and every direct dependency appearing
// exactly once under the current names. The independent source extra and its
// edge into the renamed node, the dead-end downstream sidedown, the target's
// downstream view and the standalone isolated stay excluded. The document
// order follows the new names, while the graph's stored upstream/downstream
// lists keep their original positions and the export itself changes nothing.
func TestExportSourceTargetLineageAfterRename(t *testing.T) {
	graph := scopedRenameFixture(t)
	assertConsistent(t, graph)

	if out := mustExportScoped(t, graph, "source", "report"); out != scopedRenameBefore {
		t.Fatalf("scoped export before rename =\n%s\nwant:\n%s", out, scopedRenameBefore)
	}

	// Rename the intermediate dataset mid to zmid, a name that sorts past every
	// other selected name. The node keeps both lists; every neighbor's
	// reference is rewritten in its original list position.
	mustRename(t, graph, "mid", "zmid")
	assertConsistent(t, graph)
	if _, ok := graph["mid"]; ok {
		t.Fatal("old name mid still present in graph")
	}
	if got, want := len(graph), 8; got != want {
		t.Fatalf("dataset count = %d, want %d (rename must not merge nodes)", got, want)
	}
	assertEntry(t, graph, "zmid", []string{"source", "extra"}, []string{"step", "report", "sidedown"})
	assertEntry(t, graph, "source", nil, []string{"zmid", "report"})
	assertEntry(t, graph, "extra", nil, []string{"zmid"})
	assertEntry(t, graph, "step", []string{"zmid"}, []string{"report"})
	assertEntry(t, graph, "report", []string{"source", "zmid", "step"}, []string{"view"})
	assertEntry(t, graph, "sidedown", []string{"zmid"}, nil)

	before := snapshotExportGraph(graph)
	out := mustExportScoped(t, graph, "source", "report")
	if out != scopedRenameAfterZmid {
		t.Errorf("scoped export after rename =\n%s\nwant:\n%s", out, scopedRenameAfterZmid)
	}
	doc := parseExport(t, out)

	// Same four datasets as before the rename, each exactly once, under the
	// current names and in Go string order: mid used to lead the list; zmid
	// sorts to the end.
	wantNodes := []string{"report", "source", "step", "zmid"}
	if !reflect.DeepEqual(doc.Nodes, wantNodes) {
		t.Errorf("nodes = %v, want %v", doc.Nodes, wantNodes)
	}

	// All five direct dependencies survive exactly once, still written from
	// the upstream toward the derived dataset; the three edges touching the
	// renamed node carry the new name on both endpoints.
	wantEdges := [][2]string{
		{"source", "report"},
		{"source", "zmid"},
		{"step", "report"},
		{"zmid", "report"},
		{"zmid", "step"},
	}
	if got := exportEdgeNames(doc); !reflect.DeepEqual(got, wantEdges) {
		t.Errorf("edges = %v, want %v", got, wantEdges)
	}

	// The direct relation and both longer branches through the renamed node
	// are all present: source -> report, source -> zmid -> report and
	// source -> zmid -> step -> report. report is reached over three routes
	// and zmid lies on two of them, yet each appears once.
	edgeSet := map[[2]string]bool{}
	for _, e := range wantEdges {
		edgeSet[e] = true
	}
	for _, want := range [][2]string{
		{"source", "report"}, // direct
		{"zmid", "report"},   // one hop through the renamed node
		{"zmid", "step"},     // two hops through the renamed node
		{"step", "report"},
	} {
		if !edgeSet[want] {
			t.Errorf("route edge %v missing from %v", want, wantEdges)
		}
	}

	// The old name occurs nowhere as a node or edge endpoint, while extra
	// (the renamed node's independent source), the extra -> zmid edge,
	// sidedown (a renamed-node downstream that cannot reach report), view and
	// isolated never enter the scoped document.
	assertOldNameAbsent(t, doc, "mid")
	for _, excluded := range []string{"extra", "sidedown", "view", "isolated"} {
		for _, node := range doc.Nodes {
			if node == excluded {
				t.Errorf("nodes must not contain %q: %v", excluded, doc.Nodes)
			}
		}
	}
	for _, e := range doc.Edges {
		if e.From == "extra" || e.To == "extra" {
			t.Errorf("independent source edge leaked into scoped export: %+v", e)
		}
	}

	// The export sorts into its own output without touching the graph: no
	// node, edge or stored list order changed, including the non-name-sorted
	// zmid children [step report sidedown].
	assertGraphUnchanged(t, before, graph)

	// Rename again to amid: the new name contains the old name's text and
	// sorts ahead of every other selected name. Matching stays by full name,
	// and the document order follows the current names once more.
	mustRename(t, graph, "zmid", "amid")
	assertConsistent(t, graph)
	assertEntry(t, graph, "amid", []string{"source", "extra"}, []string{"step", "report", "sidedown"})
	assertEntry(t, graph, "source", nil, []string{"amid", "report"})
	assertEntry(t, graph, "report", []string{"source", "amid", "step"}, []string{"view"})

	before = snapshotExportGraph(graph)
	out = mustExportScoped(t, graph, "source", "report")
	if out != scopedRenameAfterAmid {
		t.Errorf("scoped export after second rename =\n%s\nwant:\n%s", out, scopedRenameAfterAmid)
	}
	doc = parseExport(t, out)
	if !reflect.DeepEqual(doc.Nodes, []string{"amid", "report", "source", "step"}) {
		t.Errorf("nodes after second rename = %v", doc.Nodes)
	}
	assertOldNameAbsent(t, doc, "mid")
	assertOldNameAbsent(t, doc, "zmid")
	assertGraphUnchanged(t, before, graph)
}

// A rejected rename — the new name is already registered to another dataset —
// fails even when the occupying dataset lies outside the scoped export. The
// error names the taken name, no reference is partially rewritten, and the
// scoped export afterwards is byte-identical to the text produced before the
// failed request.
func TestExportSourceTargetLineageFailedRenameLeavesExportUntouched(t *testing.T) {
	graph := scopedRenameFixture(t)
	assertConsistent(t, graph)

	exportBefore := mustExportScoped(t, graph, "source", "report")
	if exportBefore != scopedRenameBefore {
		t.Fatalf("scoped export before failed rename =\n%s\nwant:\n%s", exportBefore, scopedRenameBefore)
	}
	before := snapshotExportGraph(graph)

	// extra is registered but excluded from the source -> report document:
	// the conflict must still block the rename, with an error naming extra.
	err := Rename(graph, "mid", "extra")
	if err == nil || !strings.Contains(err.Error(), "extra") {
		t.Fatalf("want name-in-use error naming extra, got %v", err)
	}

	// No merge, no rewritten reference: both nodes and every list keep their
	// exact pre-request state.
	assertGraphUnchanged(t, before, graph)
	if got, want := len(graph), 8; got != want {
		t.Fatalf("dataset count = %d, want %d", got, want)
	}
	assertEntry(t, graph, "mid", []string{"source", "extra"}, []string{"step", "report", "sidedown"})
	assertEntry(t, graph, "extra", nil, []string{"mid"})
	assertEntry(t, graph, "report", []string{"source", "mid", "step"}, []string{"view"})
	assertConsistent(t, graph)

	// A conflict with a name registered to the dead-end downstream — also
	// outside the export — is rejected the same way.
	err = Rename(graph, "mid", "sidedown")
	if err == nil || !strings.Contains(err.Error(), "sidedown") {
		t.Fatalf("want name-in-use error naming sidedown, got %v", err)
	}
	assertGraphUnchanged(t, before, graph)

	// The scoped export text is exactly what it was before the failed
	// requests, and still names mid rather than either rejected new name.
	exportAfter := mustExportScoped(t, graph, "source", "report")
	if exportAfter != exportBefore {
		t.Errorf("scoped export changed after rejected rename:\nbefore: %s\nafter:  %s",
			exportBefore, exportAfter)
	}
	if !strings.Contains(exportAfter, `"mid"`) {
		t.Errorf("export must still name mid after the rejected renames: %s", exportAfter)
	}
	assertGraphUnchanged(t, before, graph)
}

// After the rename, the full upstream export and the other lineage queries
// keep working against the same graph: the full export of report still
// includes the independent source extra that the scoped export excludes, and
// the upstream/downstream queries report the renamed dataset under its new
// name at its old distances.
func TestExportSourceTargetLineageAfterRenameCompatibleQueries(t *testing.T) {
	graph := scopedRenameFixture(t)
	mustRename(t, graph, "mid", "zmid")
	assertConsistent(t, graph)

	before := snapshotExportGraph(graph)

	// The full upstream export of report sees report's whole ancestry,
	// including extra and its edge into zmid — the parts the source-scoped
	// document deliberately leaves out.
	full := mustExport(t, graph, "report")
	doc := parseExport(t, full)
	wantNodes := []string{"extra", "report", "source", "step", "zmid"}
	if !reflect.DeepEqual(doc.Nodes, wantNodes) {
		t.Errorf("full export nodes = %v, want %v", doc.Nodes, wantNodes)
	}
	wantEdges := [][2]string{
		{"extra", "zmid"},
		{"source", "report"},
		{"source", "zmid"},
		{"step", "report"},
		{"zmid", "report"},
		{"zmid", "step"},
	}
	if got := exportEdgeNames(doc); !reflect.DeepEqual(got, wantEdges) {
		t.Errorf("full export edges = %v, want %v", got, wantEdges)
	}

	// The upstream query lists the renamed dataset once, at its unchanged
	// shortest distance, with explanation paths written under the new name.
	upstreams := mustUpstreams(t, graph, "report")
	assertUpstreamOnce(t, upstreams, "zmid", 1, []string{"zmid", "report"})
	assertUpstreamOnce(t, upstreams, "source", 1, []string{"source", "report"})
	assertUpstreamOnce(t, upstreams, "extra", 2, []string{"extra", "zmid", "report"})
	for _, up := range upstreams {
		if up.Dataset == "mid" {
			t.Fatalf("old name mid leaked into post-rename upstream %+v", up)
		}
		for _, hop := range up.Path {
			if hop == "mid" {
				t.Fatalf("old name mid leaked into post-rename path %+v", up)
			}
		}
	}

	// The downstream query from source reaches the same datasets as before
	// the rename, with the renamed node at its old distance under its new
	// name.
	impacts := mustImpacts(t, graph, "source")
	assertImpactOnce(t, impacts, "zmid", 1, []string{"source", "zmid"})
	assertImpactOnce(t, impacts, "report", 1, []string{"source", "report"})
	assertImpactOnce(t, impacts, "step", 2, []string{"source", "zmid", "step"})
	assertImpactOnce(t, impacts, "sidedown", 2, []string{"source", "zmid", "sidedown"})

	// The old name is unregistered for the scoped export as well.
	if out, err := ExportSourceTargetLineage(graph, "mid", "report"); err == nil {
		t.Fatalf("scoped export from old name succeeded with %q, want a not-found error", out)
	} else if !strings.Contains(err.Error(), "mid") {
		t.Errorf("error %q must name the queried old name", err)
	}

	// None of the queries changed the graph.
	assertGraphUnchanged(t, before, graph)
}

// Package chainledger implements the on-chain data governance core.
package chainledger

import "sort"

// Dataset is one ingestible on-chain data source with a declared schema version.
type Dataset struct {
	Name          string
	SchemaVersion int
	Rows          int
	Upstreams     []string
}

// Lineage records where a dataset came from, so every derived table can be traced.
type Lineage struct {
	Dataset  string
	Parents  []string
	Children []string
}

// Register links a dataset into the lineage graph and rejects cycles.
//
// Re-registering an existing dataset replaces its direct upstreams with parents
// (de-duplicated, first occurrence wins, list order preserved) while keeping its
// existing direct downstreams. Reverse edges stay consistent: upstreams removed
// from the list drop the dataset from their children, newly added upstreams gain
// it at the end of their children, and retained upstreams keep exactly one entry
// in its original position.
//
// The whole request is validated before the graph is touched, so a rejected
// registration leaves every node, edge and ordering untouched. The parents slice
// is copied: mutating it after Register returns does not affect the graph.
func Register(graph map[string]*Lineage, dataset Dataset, parents []string) error {
	if dataset.Name == "" {
		return errInvalid("dataset name is required")
	}

	// Validate up front, walking the request in input order so the first problem
	// encountered is the one reported. No graph mutation happens in this loop.
	upstreams := make([]string, 0, len(parents))
	known := map[string]bool{}
	// All cycle checks in this one request share a single memoized walk over the
	// graph as it stands now: probe records whether each visited node can reach
	// dataset.Name through existing parent edges. Candidate upstreams that come
	// from the same source or merge repeatedly (diamonds) then traverse the
	// shared lineage once instead of re-walking it per candidate. The recorded
	// conclusion is a property of the current graph, so it is never reused
	// across registrations.
	probe := newAncestorProbe(graph, dataset.Name)
	for _, parent := range parents {
		if parent == dataset.Name {
			return errInvalid("dataset " + dataset.Name + " cannot be its own parent")
		}
		if _, ok := graph[parent]; !ok {
			return errInvalid("unknown parent " + parent)
		}
		// A new edge dataset -> parent closes a cycle exactly when parent can
		// already reach dataset through existing parent edges. This covers
		// transitive paths of any depth, not only direct mutual references;
		// shared ancestors and diamond merges read as the benign merges they are
		// unless a branch genuinely leads back to dataset.
		if probe.canReach(parent) {
			return errInvalid("cycle through " + parent + " for dataset " + dataset.Name)
		}
		if !known[parent] {
			known[parent] = true
			upstreams = append(upstreams, parent)
		}
	}

	entry, existed := graph[dataset.Name]
	if !existed {
		entry = &Lineage{Dataset: dataset.Name}
	}

	// Remove reverse edges from upstreams the dataset no longer declares.
	for _, old := range entry.Parents {
		if known[old] {
			continue
		}
		if p, ok := graph[old]; ok {
			p.Children = removeChild(p.Children, dataset.Name)
		}
	}

	// Mirror every declared upstream exactly once. An existing edge keeps its
	// position; a missing edge is appended after the current children.
	for _, parent := range upstreams {
		graph[parent].Children = addChildOnce(graph[parent].Children, dataset.Name)
	}

	entry.Parents = upstreams
	if !existed {
		graph[dataset.Name] = entry
	}
	return nil
}

// Rename changes the registered name of the dataset oldName to newName while
// keeping the dataset's exact position in the lineage graph: the node keeps
// its own direct upstream and downstream lists untouched, and every neighbor
// that referenced oldName now references newName in the same list position.
// No edge is added, removed, merged or reordered, and the total number of
// datasets in the graph is unchanged. Roots, leaves and intermediate datasets
// can all be renamed.
//
// The request is validated before the graph is touched, so a rejected rename
// leaves every node, edge and list order untouched. Names match by exact
// registered value (case-sensitive). An empty old or new name is rejected as
// a missing name; an oldName absent from the graph is rejected with an error
// naming it; a newName already registered to a different dataset is rejected
// with an error naming it. Renaming a dataset to its own current name is a
// successful no-op.
func Rename(graph map[string]*Lineage, oldName, newName string) error {
	if oldName == "" {
		return errInvalid("dataset name is required")
	}
	if newName == "" {
		return errInvalid("new dataset name is required")
	}
	entry, ok := graph[oldName]
	if !ok {
		return errInvalid("dataset not found: " + oldName)
	}
	if oldName == newName {
		return nil
	}
	if _, taken := graph[newName]; taken {
		return errInvalid("dataset name already in use: " + newName)
	}

	delete(graph, oldName)
	entry.Dataset = newName
	graph[newName] = entry

	// Rewire the reverse references in place: the renamed node keeps its slot
	// in every neighbor's list, so each neighbor's ordering is preserved.
	for _, parent := range entry.Parents {
		children := graph[parent].Children
		for i, child := range children {
			if child == oldName {
				children[i] = newName
			}
		}
	}
	for _, child := range entry.Children {
		parents := graph[child].Parents
		for i, parent := range parents {
			if parent == oldName {
				parents[i] = newName
			}
		}
	}
	return nil
}

// Unregister removes a dataset registration from the lineage graph.
//
// Only a leaf dataset can be removed: a dataset with any direct downstream
// (a dataset still derived from it) is kept, regardless of how many upstreams
// it itself has. A removable dataset may still have direct upstreams; every
// one of them drops the dataset from its downstream list, in that list's
// original position, and the upstreams themselves and their other
// downstreams are untouched. A dataset with neither upstreams nor
// downstreams can also be removed. On success the name is gone from the
// graph: Impacts and Upstreams treat it as unregistered, and no empty node
// remains behind.
//
// The request is fully validated before the graph is touched, so a rejected
// removal leaves every node, edge and list order exactly as it was — no
// upstream can end up detached while the dataset stays. An empty name is
// rejected as a missing name; a non-empty name absent from the graph (also
// against an empty or nil graph) is rejected with an error naming it; a
// dataset that still has direct downstreams is rejected with an error that
// names it and states the remaining downstream. Names match by exact
// registered value (case-sensitive).
func Unregister(graph map[string]*Lineage, name string) error {
	if name == "" {
		return errInvalid("dataset name is required")
	}
	entry, ok := graph[name]
	if !ok {
		return errInvalid("dataset not found: " + name)
	}
	if len(entry.Children) > 0 {
		return errInvalid("dataset " + name + " cannot be unregistered while it still has direct downstreams")
	}

	// The dataset is a leaf, so its only edges point at its direct upstreams.
	// Drop the matching reverse edge from each one, preserving the remaining
	// order, then remove the node itself. The checks above guarantee nothing
	// points back at it, so the graph stays fully consistent.
	for _, parent := range entry.Parents {
		if p, ok := graph[parent]; ok {
			p.Children = removeChild(p.Children, name)
		}
	}
	delete(graph, name)
	return nil
}

// ancestorProbe answers "can node reach target by following parent edges?" for
// many starting nodes against one fixed, read-only snapshot of the graph, i.e.
// whether target is among each node's direct or transitive upstreams. Each node
// in the shared ancestry is resolved at most once, so candidate parents that
// descend from a common source or merge along the way reuse the same findings
// instead of each paying for a complete traversal.
type ancestorProbe struct {
	graph  map[string]*Lineage
	target string
	// resolved caches the conclusion for every fully explored node; visiting
	// marks nodes mid-resolution. Register never accepts cycles, but visiting
	// doubles as cycle protection regardless.
	resolved map[string]bool
	visiting map[string]bool
}

func newAncestorProbe(graph map[string]*Lineage, target string) *ancestorProbe {
	return &ancestorProbe{
		graph:    graph,
		target:   target,
		resolved: map[string]bool{},
		visiting: map[string]bool{},
	}
}

func (p *ancestorProbe) canReach(node string) bool {
	if node == p.target {
		return true
	}
	if hit, ok := p.resolved[node]; ok {
		return hit
	}
	if p.visiting[node] {
		return false
	}
	p.visiting[node] = true

	found := false
	if entry, ok := p.graph[node]; ok {
		for _, parent := range entry.Parents {
			if p.canReach(parent) {
				found = true
				break
			}
		}
	}
	delete(p.visiting, node)
	p.resolved[node] = found
	return found
}

// removeChild drops every occurrence of child from children, preserving the
// relative order of the remaining entries.
func removeChild(children []string, child string) []string {
	out := children[:0]
	for _, c := range children {
		if c != child {
			out = append(out, c)
		}
	}
	return out
}

// addChildOnce ensures child appears exactly once in children. An existing entry
// keeps its position (duplicate later entries are dropped); otherwise child is
// appended at the end.
func addChildOnce(children []string, child string) []string {
	out := children[:0]
	present := false
	for _, c := range children {
		if c == child {
			if present {
				continue
			}
			present = true
		}
		out = append(out, c)
	}
	if !present {
		out = append(out, child)
	}
	return out
}

// Impact names one dataset directly or indirectly downstream of an impact
// query's origin. Distance is the number of lineage edges on the shortest path
// from the origin to this dataset (a direct downstream has distance 1), and
// Path is that shortest path written from the origin to the dataset, one name
// per hop.
type Impact struct {
	Dataset  string
	Distance int
	Path     []string
}

// Impacts returns every dataset directly or indirectly downstream of origin,
// i.e. every dataset reachable from origin by following child edges. The origin
// itself is never listed, and datasets with no such connection never appear.
//
// Impacts is exactly the no-cutoff form of ImpactsWithCutoffs: it behaves as if
// every registered dataset were allowed to propagate. Distance, the
// tie-broken explanation path, result ordering, read-only graph access and
// error handling all follow the single shared lineage-query rule set
// implemented by traceLineage; only the direction is specific to Impacts:
// child edges outward, with paths written from the origin. An empty origin is
// rejected as a missing name; an origin absent from the graph (including an
// empty or nil graph) is rejected with an error naming it and no partial
// results.
func Impacts(graph map[string]*Lineage, origin string) ([]Impact, error) {
	return ImpactsWithCutoffs(graph, origin, nil)
}

// ImpactsWithCutoffs returns every dataset downstream of origin that is still
// reachable when propagation is stopped at the registered datasets named in
// cutoffs. It answers "how far does a change to origin spread if the change is
// not allowed to travel past these datasets?"
//
// A cutoff dataset that is itself reachable from origin IS included in the
// results at its own shortest distance, but the traversal never continues to
// its downstreams through it. A dataset lying past a cutoff is still listed as
// long as some other route from origin reaches it without passing any cutoff;
// only when every route runs through a cutoff does the dataset (and whatever is
// reachable through it alone) leave the result. Distances and explanation
// paths are computed solely over routes that pass no cutoff — they never reuse
// a path that the full query could take once that path has been truncated —
// with the same two-level choice as Impacts: fewest edges first, and among
// equal-length routes the lexicographically smallest full path, compared name
// by name from the origin in Go string order. Each dataset appears at most
// once, and records stay ordered by distance ascending and then by dataset
// name.
//
// With an empty (or nil) cutoff list the result is identical to Impacts. A
// repeated cutoff name acts only once; a cutoff that is registered but not
// reachable from origin changes nothing; a cutoff named after the origin
// itself is a successful query that returns a non-nil empty list, and the
// origin is still never listed as affected. Names match by exact registered
// value (case-sensitive).
//
// Like Impacts, the query is read-only: it changes no node, edge or stored
// list order, and every returned Path is an independent copy. An empty origin
// is rejected as a missing name; an origin absent from the graph (including an
// empty or nil graph) is rejected with an error naming it and nil results.
// The whole request fails (with nil results) when the cutoff list names an
// empty dataset (cutoff dataset name is required) or an unregistered one; the
// error names the offending dataset, e.g. "cutoff dataset not found: ghost".
// The origin is validated first, and cutoff problems otherwise surface in the
// cutoff list's input order.
func ImpactsWithCutoffs(graph map[string]*Lineage, origin string, cutoffs []string) ([]Impact, error) {
	hits, err := traceLineage(graph, origin, dirDownstream, cutoffs)
	if err != nil {
		return nil, err
	}
	impacts := make([]Impact, len(hits))
	for i, hit := range hits {
		impacts[i] = Impact{Dataset: hit.name, Distance: hit.distance, Path: hit.path}
	}
	return impacts, nil
}

// Upstream names one dataset directly or indirectly upstream of a provenance
// query's target. Distance is the number of lineage edges on the shortest path
// from this upstream to the target (a direct upstream has distance 1), and
// Path is that shortest path written along the actual derivation direction,
// from this upstream to the queried dataset, one name per hop.
type Upstream struct {
	Dataset  string
	Distance int
	Path     []string
}

// Upstreams returns every dataset directly or indirectly upstream of target,
// i.e. every dataset reachable from target by following parent edges. The
// target itself is never listed, its downstreams never appear, and datasets
// with no such connection never appear.
//
// Distance, the tie-broken explanation path, result ordering, read-only graph
// access and error handling all follow the single shared lineage-query rule
// set implemented by traceLineage; only the direction is specific to
// Upstreams: parent edges inward, with paths written from each source toward
// the target. An empty target is rejected as a missing name; a target absent
// from the graph (including an empty or nil graph) is rejected with an error
// naming it and no partial results.
func Upstreams(graph map[string]*Lineage, target string) ([]Upstream, error) {
	hits, err := traceLineage(graph, target, dirUpstream, nil)
	if err != nil {
		return nil, err
	}
	upstreams := make([]Upstream, len(hits))
	for i, hit := range hits {
		upstreams[i] = Upstream{Dataset: hit.name, Distance: hit.distance, Path: hit.path}
	}
	return upstreams, nil
}

// CommonUpstream names one dataset that two queried datasets can BOTH trace
// back to along upstream edges — a shared source of the pair. DistanceToFirst
// and PathToFirst describe the shortest derivation from this source to the
// first queried target; DistanceToSecond and PathToSecond describe it to the
// second queried target. Both paths are written along the actual derivation
// direction (source first, queried target last) and include both ends.
type CommonUpstream struct {
	Dataset          string
	DistanceToFirst  int
	PathToFirst      []string
	DistanceToSecond int
	PathToSecond     []string
}

// CommonUpstreams returns the datasets that are upstream of BOTH first and
// second, i.e. datasets each queried target can reach by following parent
// edges, counting each target itself as its own upstream. Comparing two
// derived datasets therefore answers not only "where did each one come from"
// but "which sources do their lineages actually share, and how far away are
// those shared points".
//
// Only the closest shared points are reported: a common source whose direct or
// indirect downstream contains ANOTHER common source is omitted. Every
// intermediate dataset on a downstream path between two common sources is
// itself common (it reaches both targets through the later shared source), so
// this frontier is decided by a single edge — a common source with a direct
// child that is also common is hidden behind that child. Several sources can
// be returned together; they are not picked by distance and need not be roots
// with no upstreams. For example, when raw derives a and b and both feed left
// and right, CommonUpstreams(left, right) returns a and b and excludes raw —
// even if raw also feeds both targets directly and is fewer edges away, a and
// b are later common sources standing between raw and the targets.
//
// Degenerate pairs follow the same rule:
//
//   - When both targets are the same dataset, the sole result is that dataset,
//     with both distances zero and both paths just [name].
//   - When one target is itself an upstream of the other, that upstream target
//     is the sole result, with distance zero on its own side; its own upstream
//     ancestors are hidden behind it.
//   - When the two lineages share no source at all, the query succeeds with a
//     non-nil empty list.
//
// Each side's distance is the minimum number of lineage edges from the source
// to that target; among equally short routes the lexicographically smallest
// full path wins, compared name by name from the source in Go string order —
// exactly the two-level rule Upstreams uses, and likewise independent of
// registration order or the stored direct-upstream list order. Each source
// appears at most once and results are ordered by source name in Go string
// order.
//
// Names match by exact registered value (case-sensitive). The targets are
// validated in input order: an empty name is rejected as a missing name, and a
// name absent from the graph (also against an empty or nil graph) is rejected
// with an error naming it; a failure returns nil results, never partial
// sources. The query is read-only, changing no node, relationship or list
// order, and every returned path is an independent copy: the two sides do not
// share backing arrays, and mutating a result can neither reach the graph nor
// another record or a later query.
func CommonUpstreams(graph map[string]*Lineage, first, second string) ([]CommonUpstream, error) {
	if first == "" {
		return nil, errInvalid("dataset name is required")
	}
	if _, ok := graph[first]; !ok {
		return nil, errInvalid("dataset not found: " + first)
	}
	if second == "" {
		return nil, errInvalid("dataset name is required")
	}
	if _, ok := graph[second]; !ok {
		return nil, errInvalid("dataset not found: " + second)
	}

	// Resolve each target's ancestor closure, the target itself included, with
	// its shortest, tie-broken explanation paths. Both closures come from the
	// single distance/path rule set shared with Upstreams; the two walks are
	// independent of one another, so the distances and paths on either side can
	// differ asymmetrically.
	toFirst := shortestLineagePaths(graph, first, dirUpstream, nil)
	toSecond := shortestLineagePaths(graph, second, dirUpstream, nil)

	// A shared source belongs to both closures.
	common := make(map[string]bool)
	for name := range toFirst.distance {
		if toSecond.reaches(name) {
			common[name] = true
		}
	}

	// Keep only the frontier: a common source with a direct child that is also
	// common has another common source strictly downstream of it and is hidden.
	// Register rejects cycles, so no child can loop back to an ancestor, and one
	// edge is sufficient to witness any longer downstream chain of common
	// sources (the intermediate nodes are common as well).
	results := make([]CommonUpstream, 0, len(common))
	for name := range common {
		hidden := false
		for _, child := range graph[name].Children {
			if common[child] {
				hidden = true
				break
			}
		}
		if hidden {
			continue
		}
		results = append(results, CommonUpstream{
			Dataset:          name,
			DistanceToFirst:  toFirst.distanceTo(name),
			PathToFirst:      toFirst.pathTo(name),
			DistanceToSecond: toSecond.distanceTo(name),
			PathToSecond:     toSecond.pathTo(name),
		})
	}
	sort.Slice(results, func(i, j int) bool { return results[i].Dataset < results[j].Dataset })
	return results, nil
}

// lineageClosure holds one BFS walk's shortest-distance and tie-broken
// explanation-path result for every dataset reachable from its start, the
// start itself included at distance 0 with path [start]. It is the single
// distance/path rule set shared by Upstreams, Impacts(WithCutoffs) and each
// side of CommonUpstreams; callers differ only in which edges they walk,
// whether they stop propagation at cutoffs, and which subset of the closure
// they report.
type lineageClosure struct {
	distance map[string]int
	best     map[string][]string
}

// reaches reports whether start can reach name.
func (c *lineageClosure) reaches(name string) bool {
	_, ok := c.distance[name]
	return ok
}

// distanceTo is the committed shortest edge distance to name; an unreachable
// name yields 0, which callers only ask for reached names.
func (c *lineageClosure) distanceTo(name string) int {
	return c.distance[name]
}

// pathTo returns an independent copy of the committed shortest path to name,
// written along the actual derivation direction so that mutating it can reach
// neither the closure's storage nor any other returned record.
func (c *lineageClosure) pathTo(name string) []string {
	return append([]string(nil), c.best[name]...)
}

// shortestLineagePaths walks direction edges from start and computes the
// shortest edge distance and the lexicographically smallest shortest path for
// every dataset in start's closure. When cutoffs is non-empty, a reachable
// cutoff node stays in the closure at its own distance but is never expanded:
// distances and paths beyond it are computed solely over routes that pass no
// cutoff. A nil cutoffs list means propagation is unrestricted.
//
// A whole BFS level commits at once, so the fewest-edge route wins and a node
// reached through several merging branches keeps exactly one candidate before
// the level commits; among equal-length routes the smallest full name sequence
// wins hop by hop from the path's beginning (see lessPath and the
// queryDirection.extendPath rule). Register rejects cycles, so equal-length
// rediscoveries only happen inside one level's candidate map. The graph is
// read only and every committed path lives in its own backing array.
func shortestLineagePaths(graph map[string]*Lineage, start string, direction queryDirection, cutoffs map[string]bool) *lineageClosure {
	closure := &lineageClosure{
		distance: map[string]int{start: 0},
		best:     map[string][]string{start: {start}},
	}
	frontier := []string{start}
	for level := 0; len(frontier) > 0; level++ {
		candidates := map[string][]string{}
		var next []string
		for _, node := range frontier {
			// A reached cutoff stays in the closure itself but is a dead end:
			// nothing propagates through it, even though a parallel route may
			// still reach the same node independently.
			if cutoffs[node] {
				continue
			}
			for _, hop := range direction.neighbors(graph[node]) {
				if closure.reaches(hop) {
					continue // reached on an earlier, strictly shorter level
				}
				candidate := direction.extendPath(closure.best[node], hop)
				if current, ok := candidates[hop]; !ok || lessPath(candidate, current) {
					if !ok {
						next = append(next, hop)
					}
					candidates[hop] = candidate
				}
			}
		}
		for _, hop := range next {
			closure.distance[hop] = level + 1
			closure.best[hop] = candidates[hop]
		}
		frontier = next
	}
	return closure
}

// queryDirection carries the only way the two lineage queries differ: which
// edges to walk and from which end an explanation path is written.
type queryDirection int

const (
	// dirDownstream follows child edges away from the query's origin and grows
	// explanation paths at the far end (origin -> ... -> dataset).
	dirDownstream queryDirection = iota
	// dirUpstream follows parent edges away from the query's target and grows
	// explanation paths at the near end (source -> ... -> target).
	dirUpstream
)

// neighbors lists the datasets one edge beyond node in the query direction.
func (d queryDirection) neighbors(node *Lineage) []string {
	if d == dirDownstream {
		return node.Children
	}
	return node.Parents
}

// extendPath grows a committed shortest path by one hop, placing the new hop
// where the explanation direction requires: a downstream hop is appended
// (origin -> node -> hop), an upstream hop is prepended (hop -> node ->
// target). The result always gets a fresh backing array, so candidates never
// alias each other, committed paths, or slices stored in the graph.
func (d queryDirection) extendPath(path []string, hop string) []string {
	extended := make([]string, len(path)+1)
	if d == dirDownstream {
		copy(extended, path)
		extended[len(extended)-1] = hop
		return extended
	}
	extended[0] = hop
	copy(extended[1:], path)
	return extended
}

// lineageHit is one direction-neutral query result: a reached dataset besides
// the query's own node, its shortest edge distance, and the lexicographically
// smallest shortest explanation path held in an independent slice.
type lineageHit struct {
	name     string
	distance int
	path     []string
}

// traceLineage runs the one query rule set shared by Impacts and Upstreams and
// returns every dataset reachable from start besides start itself. When
// cutoffs is non-empty, a reachable cutoff node is still returned but its
// neighbors are never expanded, so paths that would pass through it disappear;
// a nil cutoffs list means propagation is unrestricted.
//
// Distance, the once-per-level candidate commit and the lexicographic
// whole-path tie break all come from the shared shortestLineagePaths walk —
// the same walk CommonUpstreams uses for each side; only the direction, the
// optional cutoff frontier, and this caller's presentation differ:
//
//   - Each dataset appears at most once, however many branches merge into it.
//   - Hits are ordered by distance ascending and then by dataset name, never
//     by registration order or the stored parent/child list order.
//
// Explanation paths are written in the query direction (see extendPath). The
// graph is read only and every returned path is an independent copy. An empty
// start is rejected as a missing name; an unregistered start (also against an
// empty or nil graph) is rejected with an error naming it, with nil results;
// a registered start that reaches nothing returns a non-nil empty slice.
// Cutoffs are validated after start, in input order (duplicates acting once):
// an empty cutoff name is a missing-name error and an unregistered cutoff name
// is an error naming it; either failure yields nil results without touching
// the graph.
func traceLineage(graph map[string]*Lineage, start string, direction queryDirection, cutoffs []string) ([]lineageHit, error) {
	if start == "" {
		return nil, errInvalid("dataset name is required")
	}
	if _, ok := graph[start]; !ok {
		return nil, errInvalid("dataset not found: " + start)
	}

	// Resolve the cutoff set only after the start has been validated, walking
	// the list in input order so the first bad name is the one reported. A name
	// that repeats acts once: validation sees it once and the set holds it once.
	blocked := make(map[string]bool, len(cutoffs))
	for _, cutoff := range cutoffs {
		if cutoff == "" {
			return nil, errInvalid("cutoff dataset name is required")
		}
		if _, ok := graph[cutoff]; !ok {
			return nil, errInvalid("cutoff dataset not found: " + cutoff)
		}
		blocked[cutoff] = true
	}

	closure := shortestLineagePaths(graph, start, direction, blocked)

	hits := make([]lineageHit, 0, len(closure.distance)-1)
	for name := range closure.distance {
		if name == start {
			continue
		}
		hits = append(hits, lineageHit{
			name:     name,
			distance: closure.distanceTo(name),
			path:     closure.pathTo(name),
		})
	}
	sort.Slice(hits, func(i, j int) bool {
		if hits[i].distance != hits[j].distance {
			return hits[i].distance < hits[j].distance
		}
		return hits[i].name < hits[j].name
	})
	return hits, nil
}

// lessPath reports whether path a sorts before path b as a name sequence:
// names are compared with Go string order from the start, and an equal prefix
// makes the shorter path smaller.
func lessPath(a, b []string) bool {
	for i := 0; i < len(a) && i < len(b); i++ {
		if a[i] != b[i] {
			return a[i] < b[i]
		}
	}
	return len(a) < len(b)
}

// Roots lists datasets with no parents, in stable order.
func Roots(graph map[string]*Lineage) []string {
	var roots []string
	for name, entry := range graph {
		if len(entry.Parents) == 0 {
			roots = append(roots, name)
		}
	}
	sort.Strings(roots)
	return roots
}

type errInvalid string

func (e errInvalid) Error() string { return string(e) }

